func TestVersionCompare(t *testing.T) {
	tests := []struct {
		name string
		a    string
		b    string
		want int
	}{
		{
			name: "higher patch beats stable",
			a:    "0.6.2-nightly.202605160654.ddf1a331",
			b:    "0.6.1",
			want: 1,
		},
		{
			name: "stable beats prerelease with same base",
